select r.professor_id, r.name as professor_name, r.department, r.title, count(p.paper_id) as paper_count, coalesce(sum(p.actual_score), 0) as total_score from ms_professor r left join ms_paper p on r.professor_id = p.professor_id and p.status = '0'
and year(p.publish_date) = #{year}
where r.status = '0' group by r.professor_id, r.name, r.department, r.title, r.total_score order by total_score desc
